// 1. Active task inside an active project and active workflow state within the workspace.
// 2. Optional project_id scope and optional actor_id affinity (unassigned OR assigned to actor_id).
// 3. Workflow state category is 'backlog'/'unstarted', OR 'started' with an expired lease.
// 4. Task has no active lease (unclaimed or claim_expires_at <= NOW()).
// 5. Task has zero unresolved incoming 'blocks' relations from active non-terminal tasks.
func (q *Queries) ListAgentClaimableTasks(ctx context.Context, arg ListAgentClaimableTasksParams) ([]Task, error) {
	rows, err := q.db.Query(ctx, listAgentClaimableTasks,
		arg.WorkspaceID,
		arg.ProjectID,
		arg.ActorID,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Task{}
	for rows.Next() {
		var i Task
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.ProjectID,
			&i.ObjectiveID,
			&i.ParentTaskID,
			&i.StateID,
			&i.SequenceNumber,
			&i.Identifier,
			&i.Kind,
			&i.Priority,
			&i.Title,
			&i.Description,
			&i.AcceptanceCriteria,
			&i.EstimatePoints,
			&i.ReporterActorID,
			&i.AssigneeActorID,
			&i.ClaimedByActorID,
			&i.ClaimToken,
			&i.ClaimExpiresAt,
			&i.CompletedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
			&i.HasMarkdownDoc,
			&i.ExternalID,
			&i.LastSignalAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

